-- Mini tanda final (revisión 2026-10): 13 explicaciones que no descartaban todas las opciones -> texto nuevo y 'revisada'.
-- Guarda md5 por fila sobre el texto anterior; si no cuadran 13 actualizadas = 13 en el historial, ROLLBACK de todo.
BEGIN;
CREATE TEMP TABLE tc (id int, antes_md5 text, despues text) ON COMMIT DROP;
INSERT INTO tc VALUES
(197, '94eb647b84c6274a32f313831daf3786', 'La respuesta correcta es A) Enfermedad crónica inflamatoria intestinal tipo colitis ulcerosa. La pieza muestra una mucosa del colon roja, granular y desflecada, con múltiples formaciones polipoides, y la histología un infiltrado inflamatorio denso en la lámina propia con distorsión de las criptas. Es una colitis ulcerosa, con inflamación continua de la mucosa y pseudopólipos, que son islotes de mucosa regenerada entre las úlceras, no pólipos neoplásicos. La B es incorrecta: una colitis parasitaria, como la amebiana, produce úlceras en ojal con mucosa normal entre ellas y trofozoítos en la histología, sin distorsión crónica de las criptas. La C es incorrecta: las formaciones polipoides son pseudopólipos inflamatorios sobre una mucosa inflamada, no una poliposis. La D es incorrecta: el linfoma intestinal forma masas o infiltra la pared con linfocitos atípicos monomorfos, no un infiltrado inflamatorio mixto con distorsión de las criptas.'),
(198, 'd9d4a1e60c4c7397345ce55e3816f381', 'Esta pregunta fue anulada. No consta el motivo publicado, pero el enunciado se contradice: describe una lesión quística con áreas sólidas conectada al conducto de Wirsung sin dilatarlo, y la falta de dilatación del Wirsung no encaja con una neoplasia mucinosa papilar intraductal de rama principal, que es la que propone la opción guardada (D). La pieza muestra una lesión quística con zonas sólidas, y la histología una proliferación papilar de epitelio mucinoso. Se pueden defender tanto la D, por el componente sólido que sugiere invasión, como la B, una neoplasia de rama secundaria, que encaja mejor con un Wirsung no dilatado. La neoplasia mucinosa quística (A) no comunica con los conductos, y la sólida-pseudopapilar (C) es de mujeres jóvenes y no es mucinosa.'),
(223, '45645bd45d1e2c59656331f3867270bf', 'Esta pregunta fue anulada. Se pedía la afirmación incorrecta sobre la esofagitis eosinofílica, y varias lo son a la vez. La B es falsa: las dietas de eliminación guiadas por pruebas de alergia tienen poca eficacia, y el tratamiento inicial suele ser un inhibidor de la bomba de protones, corticoides tópicos deglutidos o una dieta empírica. La C es falsa: la inflamación es de tipo Th2, no Th1. La D es falsa: la inmunoterapia con alérgenos no es una práctica habitual en esta enfermedad. La A, la clave guardada, es en realidad cierta: el diagnóstico se confirma con endoscopia y biopsia, con 15 o más eosinófilos por campo de gran aumento.'),
(239, '790b1fdfe6a7298dbbf16fb7fb437cd6', 'La respuesta correcta es A) Naproxeno. En un paciente con cardiopatía isquémica, lo primero es intentar evitar los AINE; si son imprescindibles, el naproxeno es el que se asocia a menor riesgo cardiovascular, y con una úlcera duodenal debe asociarse a un inhibidor de la bomba de protones. La B es menos segura en este caso: el celecoxib tiene menos riesgo digestivo, pero los inhibidores selectivos de la COX-2 aumentan el riesgo de eventos cardiovasculares. La C es la menos segura: el ketorolaco tiene un riesgo digestivo muy alto. La D es menos segura: el ibuprofeno a dosis altas aumenta el riesgo cardiovascular y puede interferir con el efecto antiagregante del ácido acetilsalicílico.'),
(309, 'ecb4830042c8f0e8d5b9093ead7be46d', 'Esta pregunta fue anulada. Se pedía un signo de gravedad y de posible necesidad de ventilación mecánica en una crisis asmática, y hay más de una opción que lo es. El silencio auscultatorio (C), la clave guardada, indica que apenas entra aire y anuncia una parada respiratoria inminente, por lo que es la opción más defendible. Pero la cianosis (D) también es un signo de riesgo vital, y el pulso paradójico (A) un signo de crisis grave. Una frecuencia respiratoria por encima de 25 por minuto (B) indica una crisis grave, pero no por sí sola la necesidad de ventilación mecánica.'),
(455, '3c5993d94cf57afd78a1777f750120f1', 'La respuesta correcta es B) Le explica que el leiomioma es probablemente la causa de los sangrados y la deriva a la consulta de histeroscopias. Un leiomioma tipo 1 de la FIGO es submucoso, con menos de la mitad de su volumen dentro del miometrio y el resto protruyendo en la cavidad uterina. Los miomas submucosos son los que más se asocian a sangrado intermenstrual y reglas abundantes, y con 28 mm se pueden extirpar por histeroscopia, que permite confirmar la lesión y tratarla. La A es incorrecta: por su localización submucosa, el mioma es la causa más probable del sangrado. La C es incorrecta: la laparoscopia se usa para los miomas subserosos o intramurales; un mioma submucoso tipo 1 se extirpa por histeroscopia. La D es incorrecta: la ecografía ya caracteriza bien el mioma, y la resonancia y los análogos de la GnRH no son necesarios antes de la histeroscopia.'),
(606, '9c0404b0590a988d8592dc50b9c94b69', 'La respuesta correcta es D) Displasia epifisaria múltiple. Las radiografías muestran alteraciones bilaterales y simétricas de varias epífisis: cabezas femorales aplanadas e irregulares con artrosis de cadera, ya con una prótesis en la izquierda, y cabezas humerales también aplanadas e irregulares. En un adulto de talla baja con dolor de caderas desde la infancia, la afectación de múltiples epífisis indica una displasia epifisaria múltiple, una displasia ósea hereditaria que produce artrosis precoz. La A es incorrecta: la enfermedad de Perthes es una necrosis de la cabeza femoral en la infancia, habitualmente unilateral, y no afecta a los hombros. La B es incorrecta: la osteonecrosis multifocal aparece en adultos con factores de riesgo, como los corticoides o el alcohol, y no explica la talla baja ni el dolor desde la infancia. La C es incorrecta: la epifisiolisis es un deslizamiento de la epífisis femoral en el adolescente que afecta solo a la cadera, no a los hombros.'),
(611, '33642af951aa8c9bbd920f4d0dbe8f03', 'Esta pregunta fue anulada. No consta el motivo publicado, pero la cifra de plaquetas está mal escrita en el enunciado (15.6000/µL). La TC muestra opacidades en vidrio deslustrado y consolidaciones bilaterales, compatibles con una hemorragia alveolar. Si las plaquetas son normales, unas 156.000/µL, un fracaso renal agudo con hematuria, proteinuria y hemorragia alveolar es un síndrome renopulmonar, por una vasculitis o una enfermedad anti-membrana basal, y la opción más defendible es la clave guardada (B), que se trata con inmunosupresores y plasmaféresis. Si fueran 15.600/µL, la anemia con trombopenia y fracaso renal haría pensar en una microangiopatía trombótica (C). La neumonía con necrosis tubular (A) no explica la hematuria y la proteinuria, y la insuficiencia cardiaca (D) no explica un fracaso renal parenquimatoso con sedimento activo.'),
(624, 'a327edaeecb89a552708cfc0b19c8517', 'Esta pregunta fue anulada. Se pedía la afirmación incorrecta sobre la exploración pupilar, y hay dos. La A, la clave guardada, es incorrecta: el reflejo de la visión próxima se explora haciendo que el paciente mire un objeto cercano, no con una linterna; la linterna alternante sirve para buscar el defecto pupilar aferente relativo. La B también es incorrecta: el defecto pupilar aferente aparece en las enfermedades del nervio óptico y en las enfermedades retinianas extensas, no en las poco extensas. La C es cierta: si se lesiona la vía eferente del III par, la pupila de ese lado no se contrae ni de forma directa ni consensuada. La D es cierta: la anisocoria que aumenta en la oscuridad, con la pupila afectada más pequeña, indica una lesión simpática.'),
(755, 'a13fb91689c0da1437d57f87d7c04eeb', 'Esta pregunta fue anulada. Se pedía la afirmación correcta sobre el tratamiento de la foliculitis, y ninguna lo es con claridad. La foliculitis suele deberse a Staphylococcus aureus, por lo que la D es falsa, y las formas localizadas se tratan con antibióticos tópicos como la mupirocina o el ácido fusídico, por lo que la A es falsa. La B, la clave guardada, tampoco es la recomendación habitual: en los alérgicos a la penicilina se prefieren la clindamicina, la doxiciclina o el cotrimoxazol, porque el ciprofloxacino cubre mal el estafilococo. La C no tiene apoyo: una valvulopatía reumática no obliga a tratar por vía oral una foliculitis superficial.'),
(814, 'd826de3eb902b5d9a54194ece2ae728c', 'Esta pregunta fue anulada. No consta el motivo publicado. El frotis muestra numerosos hematíes con espículas irregulares, acantocitos, y un neutrófilo. En un paciente con cirrosis alcohólica, anemia macrocítica, bilirrubina de predominio no conjugado y haptoglobina indetectable, es una anemia hemolítica por acantocitos de la cirrosis avanzada, y la opción más defendible es la D (acantocitosis), no la clave guardada (B). La saturación de transferrina y la ferritina algo elevadas son frecuentes en la enfermedad hepática alcohólica y no bastan para diagnosticar una hemocromatosis. La hepatitis alcohólica (A) no explica la hemólisis ni la bilirrubina no conjugada, y la anemia hemolítica autoinmune (C) no produce acantocitos.'),
(938, '205b39bbeb0dbe0bc8cdf28d4f528680', 'La respuesta correcta es A) Hiponatremia inducida por tiazidas. La paciente tiene una hiponatremia de 122 mEq/L con una osmolalidad plasmática baja, de 257 mOsm/kg, es decir, una hiponatremia hipotónica verdadera, sin signos de deshidratación ni edemas y con un sodio urinario de 45 mEq/L. Empezó hace un mes con hidroclorotiazida, con una analítica previa normal. Las tiazidas causan hiponatremia porque impiden diluir la orina en el túbulo distal y favorecen la acción de la ADH, sobre todo en mujeres mayores. La B es incorrecta: la insuficiencia suprarrenal suele acompañarse de hipotensión e hiperpotasemia, y la paciente tiene la presión arterial y el potasio normales. La C es incorrecta: en la potomanía la orina está muy diluida y el sodio urinario es bajo, no de 45 mEq/L. La D es incorrecta: la pseudohiponatremia cursa con una osmolalidad plasmática normal o alta, y aquí está baja.'),
(939, '6256f733490ab23c5d1a0e98de24ec4d', 'Esta pregunta fue anulada. No consta el motivo publicado, pero el enunciado mezcla datos de dos enfermedades: la febrícula y el tiroides doloroso orientan a una tiroiditis subaguda, mientras que el aumento de la vascularización en la ecografía es propio de la enfermedad de Graves, ya que en la tiroiditis está disminuida. La opción más defendible es la clave guardada (A): en la tiroiditis subaguda hay TSH baja y T4 libre alta por liberación de hormona almacenada, anticuerpos estimulantes negativos y captación baja en la gammagrafía. La B sería el patrón de la enfermedad de Graves. La C es incompatible, porque una TSH alta con T4 libre alta no corresponde a ninguno de los dos cuadros. La D combina anticuerpos positivos con captación baja, que no corresponde a ninguno.');
CREATE TEMP TABLE h0 ON COMMIT DROP AS SELECT count(*) n FROM explicaciones_historial;
SET LOCAL mir.motivo = 'Mini tanda final 2026-10';
DO $$ DECLARE n int; h int; BEGIN
  WITH u AS (UPDATE preguntas p SET explicacion = tc.despues, explicacion_calidad = CASE WHEN p.anulada THEN p.explicacion_calidad ELSE 'revisada' END
    FROM tc WHERE p.id = tc.id AND md5(p.explicacion) = tc.antes_md5 AND p.explicacion_calidad <> 'controversia' RETURNING 1)
  SELECT count(*) INTO n FROM u;
  SELECT (SELECT count(*) FROM explicaciones_historial) - h0.n INTO h FROM h0;
  IF n <> 13 OR h <> 13 THEN RAISE EXCEPTION 'actualizadas %, historial +% (esperado 13): ROLLBACK de todo', n, h; END IF;
  RAISE NOTICE 'actualizadas %, historial +%', n, h;
END $$;
COMMIT;
